function repoChangeSummary(changes) {
  const parts = [];
  if (changes.files === 0 && changes.commits === 0) {
    parts.push("No file changes");
  } else {
    if (changes.files > 0) {
      parts.push(
        `${changes.files} ${changes.files === 1 ? "file" : "files"} changed`
      );
    }
    if (changes.commits > 0) {
      parts.push(
        `${changes.commits} ${changes.commits === 1 ? "commit" : "commits"}`
      );
    }
    if (changes.uncommitted) parts.push("Not committed");
  }
  if (changes.switchedToBranch) {
    parts.push(`Now on ${changes.switchedToBranch}`);
  }
  return parts.join(" · ");
}
